def investigate(context, acquire):
    def make_decoder():
        return {'pending': []}

    def feed(decoder, data):
        pending = decoder['pending']
        stream = pending + list(data)
        decoder['pending'] = []
        index = 0
        total = 0
        limit = len(stream)
        while index < limit:
            first = stream[index]
            if first < 128:
                total += 1
                index += 1
                continue
            if first < 192:
                raise ValueError('invalid utf8')
            if first < 224:
                width = 2
                low = 128
                high = 191
            elif first < 240:
                width = 3
                if first == 224:
                    low = 160
                elif first == 237:
                    high = 159
                else:
                    low = 128
                    high = 191
            elif first < 248:
                width = 4
                if first == 240:
                    low = 144
                elif first == 244:
                    high = 143
                else:
                    low = 128
                    high = 191
            else:
                raise ValueError('invalid utf8')
            if index + width > limit:
                decoder['pending'] = stream[index:]
                return total
            valid = True
            for offset in range(1, width):
                byte = stream[index + offset]
                if byte < low or byte > high:
                    valid = False
                    break
                if offset == 1 and width > 2:
                    low = 128
                    high = 191
            if not valid:
                raise ValueError('invalid utf8')
            total += 1
            index += width
        return total

    def finish(decoder):
        if decoder['pending']:
            raise ValueError('incomplete utf8')
        return 0

    events = context['events']
    decoder = make_decoder()
    count = 0
    status = 'open'
    for event in events:
        op = event['op']
        if op == 'feed':
            if status != 'open':
                raise ValueError('illegal event')
            count += feed(decoder, event['bytes'])
        elif op == 'finish':
            if status != 'open':
                raise ValueError('illegal event')
            count += finish(decoder)
            status = 'finished'
        elif op == 'reset':
            decoder = make_decoder()
            count = 0
            status = 'open'
        else:
            raise ValueError('illegal event')
    return {'count': count, 'status': status}
